let locale='ja';
export function setLocale(value){locale=['ja','zh','en'].includes(value)?value:'ja';return locale;}
export function getLocale(){return locale;}
export function t(key,values={}){const s=STRINGS[key]?.[locale]??key;return s.replace(/\{(\w+)\}/g,(_,name)=>String(values[name]??'{'+name+'}'));}
export function applyLocale(root=document){root.documentElement.lang=locale;root.title=t('pageTitle');root.querySelectorAll('[data-i18n]').forEach(n=>n.textContent=t(n.dataset.i18n));for(const attr of ['aria-label','placeholder'])root.querySelectorAll('[data-i18n-'+attr+']').forEach(n=>n.setAttribute(attr,t(n.getAttribute('data-i18n-'+attr))));}

